// Short factual sentences built from detector facts.
//
// RULES (CD-4, CD-10 in docs/council-synthesis.md; Hard rule 1 and 7 in CLAUDE.md):
//   * Every sentence is assembled from fields of a detector result by a template. Nothing is generated by a language model.
//   * A sentence states only what the facts say: where pieces stand, what attacks what, how many times, what a verified
//     two-move check found, and COUNTED material (pawn 1, knight 3, bishop 3, rook 5, queen 9).
//   * No evaluative words ("strong", "weak", "good", "winning", "better", "dangerous"). A tactic that was checked and
//     does not hold gets a sentence saying which checked condition failed, not a verdict on the position.
//   * "works" claims are phrased with their checking depth ("checked one reply deep").

import type { Color, PieceRef, PieceSymbol, Square } from './board.ts'
import { COLOR_NAME, PIECE_NAME, opposite } from './board.ts'
import { MATE_SCORE } from './exchange.ts'
import type { ConceptFacts, ConceptName } from './detectors/index.ts'
import type { ForkDetail } from './detectors/fork.ts'
import type { PinDetail } from './detectors/pin.ts'
import type { SkewerDetail } from './detectors/skewer.ts'
import type { DiscoveredDetail } from './detectors/discovered.ts'
import type { HangingPiece } from './detectors/hanging.ts'
import type { TrappedPiece } from './detectors/trapped.ts'
import type { BackRankDetail } from './detectors/backrank.ts'
import type { PassedPawn } from './detectors/passedPawn.ts'
import type { FileInfo } from './detectors/openFile.ts'
import type { OutpostInfo } from './detectors/outpost.ts'
import type { PairStatus } from './detectors/bishopPair.ts'
import type { MaterialCount } from './detectors/materialCount.ts'
import type { PieceAttackInfo } from './detectors/attackCount.ts'

export interface Explanation {
  concept: ConceptName | 'material' | 'attackCount'
  /** One or two short sentences. */
  text: string
  /** true: a tactic that was checked to work; false: checked and does not work; null: a plain structural fact. */
  works: boolean | null
}

// ---------------------------------------------------------------------------------------------------------------------
// small text helpers
// ---------------------------------------------------------------------------------------------------------------------

const the = (p: { type: PieceSymbol; square: Square }): string => `the ${PIECE_NAME[p.type]} on ${p.square}`
const The = (p: { type: PieceSymbol; square: Square }): string => `The ${PIECE_NAME[p.type]} on ${p.square}`

function list(items: string[]): string {
  if (items.length <= 1) return items.join('')
  return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`
}

const points = (n: number): string => `${n} point${n === 1 ? '' : 's'}`
const times = (n: number): string => (n === 1 ? 'once' : n === 2 ? 'twice' : `${n} times`)

function gainPhrase(color: Color, gain: number): string {
  if (gain >= MATE_SCORE) return `${COLOR_NAME[color]} can then checkmate`
  return `${COLOR_NAME[color]} can then win at least ${points(gain)} of counted material`
}

// ---------------------------------------------------------------------------------------------------------------------
// per-concept sentences
// ---------------------------------------------------------------------------------------------------------------------

export function explainFork(d: ForkDetail): string {
  const targets = list(d.targets.map(t => the(t)))
  let s = `${The(d.forker)} attacks ${targets}.`
  const enemy = opposite(d.forker.color)
  if (d.works) {
    s += ` Whatever ${COLOR_NAME[enemy]} replies, ${gainPhrase(d.forker.color, d.guaranteedGain)} (checked one reply deep).`
  } else if (d.failure === 'forker-capturable-by-cheaper-piece') {
    const c = d.capturedBy.find(x => x.cheaper)
    s += ` But ${the(d.forker)} can be captured by the ${c ? PIECE_NAME[c.type] : 'piece'} on ${c?.square}, which is worth less.`
  } else if (d.failure === 'defender-can-save-enough') {
    s += ` The check found a reply (${d.bestDefence}) after which ${COLOR_NAME[d.forker.color]} cannot win material by capturing one of them.`
  } else if (d.failure === 'forker-side-to-move') {
    s += ` It is ${COLOR_NAME[d.forker.color]}'s move, so this is a capture to make now rather than a fork.`
  }
  return s
}

export function explainPin(d: PinDetail): string {
  const pinner = The(d.pinner)
  let s: string
  if (d.kind === 'absolute') {
    s = `${pinner} pins ${the(d.pinned)} to ${the(d.behind)}: the ${PIECE_NAME[d.pinned.type]} cannot legally leave the line.`
  } else {
    s = `${pinner} attacks ${the(d.pinned)}, and behind it on the same line stands ${the(d.behind)}, which is worth more; if the ${PIECE_NAME[d.pinned.type]} moves, the ${PIECE_NAME[d.behind.type]} can be captured.`
  }
  s += ` ${The(d.pinned)} is attacked ${times(d.attackers.length)} and defended ${times(d.defenders.length)}.`
  if (d.works) {
    s += ` ${gainPhrase(d.pinner.color, d.guaranteedGain)}${d.pinnerToMove ? '' : `, whatever ${COLOR_NAME[opposite(d.pinner.color)]} replies`} (checked one reply deep).`
  } else {
    s += ` The check found no way for ${COLOR_NAME[d.pinner.color]} to win material by force from this alone.`
  }
  if (d.shieldsMovedPiece) s += ` The pinned piece cannot capture the piece that just moved.`
  return s
}

export function explainSkewer(d: SkewerDetail): string {
  const front = d.front.type === 'k' ? `the king on ${d.front.square}` : the(d.front)
  let s = `${The(d.attacker)} attacks ${front}, and behind it on the same line stands ${the(d.back)}, which is worth less.`
  if (d.works) {
    s += ` Whatever ${COLOR_NAME[opposite(d.attacker.color)]} replies, ${gainPhrase(d.attacker.color, d.guaranteedGain)} (checked one reply deep).`
  } else {
    s += ` The check found no way for ${COLOR_NAME[d.attacker.color]} to win material by force from this alone.`
  }
  return s
}

export function explainDiscovered(d: DiscoveredDetail): string {
  if (d.kind === 'battery') {
    return `${The(d.unmasker)} stands between ${the(d.slider)} and ${the(d.target)}; if it moves, the ${PIECE_NAME[d.slider.type]} attacks the ${PIECE_NAME[d.target.type]}${d.check ? ' (a check)' : ''}.`
  }
  let s = `Moving the ${PIECE_NAME[d.unmasker.type]} from ${d.unmasker.square} uncovers ${the(d.slider)}'s attack on ${the(d.target)}${d.check ? ' (a discovered check)' : ''}.`
  if (d.doubleCheck) s += ' The moved piece gives check as well (double check).'
  if (d.moverTargets.length > 0) s += ` The moved piece also attacks ${list(d.moverTargets.map(t => the(t)))}.`
  if (d.works) s += ` ${gainPhrase(d.slider.color, d.guaranteedGain)} whatever the reply (checked one reply deep).`
  return s
}

export function explainHanging(h: HangingPiece): string {
  const attackers = list(h.attackers.map(a => the(a)))
  const owner = COLOR_NAME[h.piece.color]
  if (h.reason === 'undefended') {
    return `${owner}'s ${PIECE_NAME[h.piece.type]} on ${h.piece.square} is attacked by ${attackers} and no ${owner} piece defends it.`
  }
  return `${owner}'s ${PIECE_NAME[h.piece.type]} on ${h.piece.square} is attacked by ${attackers}, and one of the attackers is worth less than the ${PIECE_NAME[h.piece.type]}.`
}

export function explainTrapped(t: TrappedPiece): string {
  const owner = COLOR_NAME[t.piece.color]
  const n = t.moves.length
  const moves = n === 0 ? 'It has no legal move.' : `Each of its ${n} legal move${n === 1 ? '' : 's'} loses material (${list(t.moves.map(m => m.to))}).`
  let s = `${owner}'s ${PIECE_NAME[t.piece.type]} on ${t.piece.square} is attacked and can be captured for a net gain of ${points(t.lossIfLeft)}. ${moves}`
  s += t.rescuable ? ' Another move may save it.' : ' No other legal move saves it (checked one move deep).'
  return s
}

export function explainBackRank(d: BackRankDetail): string {
  const owner = COLOR_NAME[d.color]
  const blockers = list(d.blockers.map(b => b.square))
  if (d.mate) {
    return `Checkmate on the back rank: the king on ${d.king} is attacked along its rank, and its own pieces on ${blockers} block every square in front of it.`
  }
  let s = `${owner}'s king on ${d.king} is on its back rank and its own pieces on ${blockers} occupy every square in front of it.`
  if (d.mateInOne) s += ` ${d.mateInOne.san} is checkmate.`
  return s
}

export function explainPassedPawn(p: PassedPawn): string {
  const owner = COLOR_NAME[p.pawn.color]
  const enemy = COLOR_NAME[opposite(p.pawn.color)]
  const file = p.pawn.square[0]
  let s = `The ${owner} pawn on ${p.pawn.square} is a passed pawn: no ${enemy} pawn stands in front of it on the ${file}-file or the neighbouring files. It needs ${p.stepsToPromotion} move${p.stepsToPromotion === 1 ? '' : 's'} to reach the last rank.`
  if (p.protectedByPawn) s += ' A pawn defends it.'
  if (p.blockedBy) s += ` ${The(p.blockedBy)} stands directly in front of it.`
  if (p.connectedWith.length > 0) s += ` It is next to the passed pawn on ${list(p.connectedWith)}.`
  return s
}

export function explainFile(f: FileInfo): string {
  const heavy = f.heavyPieces.length > 0 ? ` Rooks and queens on it: ${list(f.heavyPieces.map(h => `${COLOR_NAME[h.color]} ${PIECE_NAME[h.type]} on ${h.square}`))}.` : ''
  if (f.kind === 'open') return `The ${f.file}-file is open: there is no pawn on it.${heavy}`
  const c = f.forColor as Color
  return `The ${f.file}-file is half-open for ${COLOR_NAME[c]}: ${COLOR_NAME[c]} has no pawn on it, but ${COLOR_NAME[opposite(c)]} has.${heavy}`
}

export function explainOutpost(o: OutpostInfo): string {
  const owner = COLOR_NAME[o.color]
  const enemy = COLOR_NAME[opposite(o.color)]
  const what = o.piece ? the(o.piece) : `the square ${o.square}`
  const sup = `a ${owner} pawn on ${list(o.supportedBy)} defends ${o.piece ? 'it' : o.square}`
  if (o.challengedBy.length === 0) {
    return `${what[0].toUpperCase()}${what.slice(1)} stands on an outpost: ${sup}, and no ${enemy} pawn can ever attack ${o.square}.`
  }
  return `${what[0].toUpperCase()}${what.slice(1)} stands on a square that ${sup}, but the ${enemy} pawn${o.challengedBy.length === 1 ? '' : 's'} on ${list(o.challengedBy)} can still advance to attack it.`
}

export function explainBishopPair(p: PairStatus): string {
  const side = (c: Color) => `${COLOR_NAME[c]} has ${p[c] ? 'the bishop pair' : 'no bishop pair'} (bishops on ${list(p.bishops[c]) || 'no square'})`
  return `${side('w')}; ${side('b')}.`
}

export function explainMaterial(m: MaterialCount): string {
  const side = (c: Color) => {
    const s = m[c]
    return `${COLOR_NAME[c]} ${s.total} (${s.queens} queen${s.queens === 1 ? '' : 's'}, ${s.rooks} rook${s.rooks === 1 ? '' : 's'}, ${s.bishops} bishop${s.bishops === 1 ? '' : 's'}, ${s.knights} knight${s.knights === 1 ? '' : 's'}, ${s.pawns} pawn${s.pawns === 1 ? '' : 's'})`
  }
  const diff = m.balance === 0 ? 'The counts are equal.' : `${COLOR_NAME[m.ahead as Color]} has ${points(Math.abs(m.balance))} more.`
  return `Counted material (pawn 1, knight 3, bishop 3, rook 5, queen 9): ${side('w')}; ${side('b')}. ${diff}`
}

export function explainAttackInfo(a: PieceAttackInfo): string {
  return `${COLOR_NAME[a.piece.color]}'s ${PIECE_NAME[a.piece.type]} on ${a.piece.square} is attacked ${times(a.attackers.length)} and defended ${times(a.defenders.length)}.`
}

// ---------------------------------------------------------------------------------------------------------------------
// everything at once
// ---------------------------------------------------------------------------------------------------------------------

export interface ExplainOptions {
  /** Restrict to these concepts (default: all that were found). */
  only?: ConceptName[]
  /** Also list tactics whose structure was found but whose check failed (default true: they make good contrast items). */
  includeFailed?: boolean
  /** Add the material count sentence (default false). */
  includeMaterial?: boolean
  /** At most this many sentences per concept (default 3). */
  maxPerConcept?: number
}

/** When the analysed move is itself checkmate, "can then checkmate" is replaced by "The move is checkmate.". */
function mateNote(text: string): string {
  return text.replace(/( Whatever [A-Za-z]+ replies,)? ?[A-Za-z]+ can then checkmate(?:, whatever [A-Za-z]+ replies| whatever the reply)? \(checked one reply deep\)\./, ' The move is checkmate.')
}

/** Turn the facts of detectConcepts() into short factual sentences, most informative first. */
export function explainFacts(f: ConceptFacts, opts: ExplainOptions = {}): Explanation[] {
  const out = explainFactsRaw(f, opts)
  return f.move?.isCheckmate ? out.map(e => ({ ...e, text: mateNote(e.text) })) : out
}

function explainFactsRaw(f: ConceptFacts, opts: ExplainOptions): Explanation[] {
  const max = opts.maxPerConcept ?? 3
  const includeFailed = opts.includeFailed ?? true
  const only = opts.only ? new Set(opts.only) : null
  const out: Explanation[] = []
  const want = (c: ConceptName) => !only || only.has(c)
  const push = (concept: Explanation['concept'], text: string, works: boolean | null) => out.push({ concept, text, works })

  if (want('fork')) for (const d of f.fork.details.filter(d => includeFailed || d.works).slice(0, max)) push('fork', explainFork(d), d.works)
  if (want('pin')) for (const d of f.pin.details.filter(d => includeFailed || d.works).slice(0, max)) push('pin', explainPin(d), d.works)
  if (want('skewer')) for (const d of f.skewer.details.filter(d => includeFailed || d.works).slice(0, max)) push('skewer', explainSkewer(d), d.works)
  if (want('discoveredAttack')) for (const d of f.discovered.details.filter(d => includeFailed || d.works).slice(0, max)) push('discoveredAttack', explainDiscovered(d), d.kind === 'executed' ? d.works : null)
  if (want('doubleCheck') && f.doubleCheck.found) {
    const d = f.doubleCheck.details[0]
    push('doubleCheck', `The king on ${d.king.square} is attacked by ${list(d.checkers.map(c => the(c)))} at the same time (double check).`, true)
  }
  if (want('hangingPiece')) {
    if (f.hanging.capturedHanging) {
      const h = f.hanging.capturedHanging
      push('hangingPiece', `The move captures ${COLOR_NAME[h.piece.color]}'s ${PIECE_NAME[h.piece.type]} on ${h.piece.square}, which was ${h.reason === 'undefended' ? 'undefended' : 'attacked by a piece worth less'}.`, null)
    }
    for (const h of f.hanging.details.slice(0, max)) push('hangingPiece', explainHanging(h), null)
  }
  if (want('trappedPiece')) for (const t of f.trapped.details.slice(0, max)) push('trappedPiece', explainTrapped(t), !t.rescuable)
  if (want('backRank')) for (const d of f.backRank.details.slice(0, max)) push('backRank', explainBackRank(d), d.mate || d.mateInOne !== null)
  if (want('passedPawn')) for (const p of (f.move ? f.passedPawn.created : f.passedPawn.details).slice(0, max)) push('passedPawn', explainPassedPawn(p), null)
  if (want('openFile')) for (const fi of (f.move ? f.openFile.created : f.openFile.details).slice(0, max)) push('openFile', explainFile(fi), null)
  if (want('outpost')) for (const o of [...f.outpost.details, ...f.outpost.challengeable].slice(0, max)) push('outpost', explainOutpost(o), null)
  if (want('bishopPair') && f.bishopPair.found) push('bishopPair', explainBishopPair(f.bishopPair.after), null)
  if (want('isolatedDoubled')) {
    const src = f.move ? f.isolatedDoubled.created : f.isolatedDoubled.details
    for (const p of src.isolated.slice(0, max)) {
      const file = p.square[0]
      push('isolatedDoubled', `The ${COLOR_NAME[p.color]} pawn on ${p.square} is isolated: ${COLOR_NAME[p.color]} has no pawn on the neighbouring files next to the ${file}-file.`, null)
    }
    for (const d of src.doubled.slice(0, max)) {
      push('isolatedDoubled', `${COLOR_NAME[d.color]} has doubled pawns on the ${d.file}-file (${list(d.squares)}).`, null)
    }
  }
  if (opts.includeMaterial) push('material', explainMaterial(f.material.details[0]), null)
  return out
}

export type { PieceRef }
